const std = @import("std");

pub fn main(init: std.process.Init) !void {
    var buf: [256]u8 = undefined;
    var stdout: std.Io.File.Writer = .init(.stdout(), init.io, &buf);
    const out = &stdout.interface;
    for (1..16) |i| {
        if (i % 15 == 0) {
            try out.writeAll("FizzBuzz\n");
        } else if (i % 3 == 0) {
            try out.writeAll("Fizz\n");
        } else if (i % 5 == 0) {
            try out.writeAll("Buzz\n");
        } else {
            try out.print("{d}\n", .{i});
        }
    }
    try out.flush();
}

higher-order.code:
const std = @import("std");

pub fn main(init: std.process.Init) !void {
    var buf: [64]u8 = undefined;
    var stdout: std.Io.File.Writer = .init(.stdout(), init.io, &buf);
    const out = &stdout.interface;
    // No closures or iterator adaptors: an explicit loop over a range.
    var first = true;
    for (1..11) |n| {
        if (n % 2 != 0) continue;
        if (!first) try out.writeAll(" ");
        try out.print("{d}", .{n * n});
        first = false;
    }
    try out.writeAll("\n");
    try out.flush();
}

shapes.code:
const std = @import("std");

// A tagged union: the enum tag is checked by an exhaustive `switch`.
const Shape = union(enum) {
    rectangle: struct { width: u32, height: u32 },
    triangle: struct { base: u32, height: u32 },

    fn area(self: Shape) u32 {
        return switch (self) {
            .rectangle => |r| r.width * r.height,
            .triangle => |t| t.base * t.height / 2,
        };
    }
};

pub fn main(init: std.process.Init) !void {
    var buf: [64]u8 = undefined;
    var stdout: std.Io.File.Writer = .init(.stdout(), init.io, &buf);
    const out = &stdout.interface;
    const shapes = [_]Shape{
        .{ .rectangle = .{ .width = 3, .height = 4 } },
        .{ .triangle = .{ .base = 10, .height = 3 } },
    };
    for (shapes) |s| {
        const name = switch (s) {
            .rectangle => "Rectangle",
            .triangle => "Triangle",
        };
        try out.print("{s}: {d}\n", .{ name, s.area() });
    }
    try out.flush();
}

