const std = @import("std");

// Types are comptime values: a generic type is a function that returns one.
fn Pair(comptime T: type) type {
    return struct {
        a: T,
        b: T,
        fn max(self: @This()) T {
            return @max(self.a, self.b);
        }
    };
}

fn fib(n: u64) u64 {
    return if (n < 2) n else fib(n - 1) + fib(n - 2);
}

pub fn main(init: std.process.Init) !void {
    var buf: [128]u8 = undefined;
    var stdout: std.Io.File.Writer = .init(.stdout(), init.io, &buf);
    const p = Pair(f32){ .a = 2.5, .b = 1.5 };
    const f = comptime fib(10); // run by the compiler: the binary just holds 55
    try stdout.interface.print("max={d} fib(10)={d}\n", .{ p.max(), f });
    try stdout.interface.flush();
}
